    border-bottom: 2px solid #CE942F;
    padding-bottom: 1px;
  }

  .article-back:hover { color: #CE942F; text-decoration: none; }

  .article-tags {
    display: flex;
    gap: 0.35rem;
    flex-wrap: wrap;
  }

  .article-tag {
    font-family: "Inter", sans-serif;
    font-size: 0.62rem;
    font-weight: 600;
    padding: 0.15rem 0.5rem;
    border-radius: 3px;
    text-transform: uppercase;
    letter-spacing: 0.3px;
    background: #f5e6d8;
    color: #7a4a2e;
  }
</style>

<div class="article-header">
  <span class="article-eyebrow">{% if page.lang == "de" %}KI × Kunst &amp; Museum{% else %}AI × Art &amp; Museum{% endif %}</span>
  <h1 class="article-title">{{ page.title }}</h1>
  <div class="article-meta">
    {% if page.lang == "de" %}
    <span>{{ page.date | date: "%-d" }}. {{ site.data.de_months[page.date | date: "%m"] }} {{ page.date | date: "%Y" }}</span>
    {% else %}
    <span>{{ page.date | date: "%B %-d, %Y" }}</span>
    {% endif %}
    {% if page.read_time %}
    <span class="meta-sep">·</span>
    <span>{{ page.read_time }} {% if page.lang == "de" %}Min. Lesezeit{% else %}min read{% endif %}</span>
    {% endif %}
    {% if page.author %}
    <span class="meta-sep">·</span>
    <span>{{ page.author }}</span>
    {% endif %}
  </div>
</div>

<div class="article-body">
  {{ content }}
</div>

<div class="article-footer">
  {% if page.lang == "de" %}
  <a href="/de/artikel/" class="article-back">← Alle Artikel</a>
  {% else %}
  <a href="/articles/" class="article-back">← All Articles</a>
  {% endif %}
  {% if page.tags %}
  <div class="article-tags">
    {% for tag in page.tags %}
    <span class="article-tag">{{ tag }}</span>
    {% endfor %}
  </div>
  {% endif %}
</div>

