$white:      #fff;
$lightgrey:  #eee;
$black:      #000;

$theme-color: $blue;
$theme-color-dark: darken($theme-color, 10%);

$post-date-color: #9a9a9a;
$title-color: #ce942f;
$masthead-title-small-color: #c0c0c0;

/* Layout */
$reverse-layout: true;
$overlay-sidebar: false;

/* Font stack */
$font-serif: "Lora", Georgia, "Times New Roman", serif;
$font-sans: "Cormorant Garamond", Georgia, serif;
$font-ui: "Inter", "Helvetica Neue", Helvetica, sans-serif;
$font-font-awesome: FontAwesome;

